// svgbob: ASCII art to SVG renderer
// Reimplementation from observed behavior.

use std::fmt::Write;

pub struct Settings {
    pub font_family: String,
    pub font_size: i32,
    pub background: String,
    pub fill_color: String,
    pub stroke_color: String,
    pub stroke_width: f64,
    pub scale: f64,
}

impl Default for Settings {
    fn default() -> Self {
        Self {
            font_family: "Iosevka Fixed, monospace".to_string(),
            font_size: 14,
            background: "white".to_string(),
            fill_color: "black".to_string(),
            stroke_color: "black".to_string(),
            stroke_width: 2.0,
            scale: 1.0,
        }
    }
}

const CELL_W: i32 = 8;
const CELL_H: i32 = 16;

#[derive(Clone, Copy)]
enum NumVal {
    Int(i32),
    Float(f64),
}

impl NumVal {
    fn times(self, s: f64) -> NumVal {
        match self {
            NumVal::Int(v) => {
                let r = (v as f64) * s;
                if (r.fract()).abs() < 1e-9 {
                    NumVal::Int(r.round() as i32)
                } else {
                    NumVal::Float(r)
                }
            }
            NumVal::Float(v) => NumVal::Float(v * s),
        }
    }
    fn write(self, out: &mut String) {
        match self {
            NumVal::Int(v) => {
                write!(out, "{}", v).unwrap();
            }
            NumVal::Float(v) => {
                if v.fract().abs() < 1e-9 {
                    write!(out, "{}", v.round() as i64).unwrap();
                } else {
                    write!(out, "{}", v).unwrap();
                }
            }
        }
    }
}

fn sn(v: i32) -> NumVal {
    NumVal::Int(v)
}

struct Grid {
    rows: Vec<Vec<char>>,
}

impl Grid {
    fn from_str(input: &str) -> Self {
        let rows: Vec<Vec<char>> = input.lines().map(|l| l.chars().collect()).collect();
        Grid { rows }
    }

    fn get(&self, r: i32, c: i32) -> char {
        if r < 0 || c < 0 {
            return ' ';
        }
        let r = r as usize;
        let c = c as usize;
        if r >= self.rows.len() {
            return ' ';
        }
        if c >= self.rows[r].len() {
            return ' ';
        }
        self.rows[r][c]
    }

    fn num_rows(&self) -> i32 {
        self.rows.len() as i32
    }

    fn max_cols(&self) -> i32 {
        self.rows.iter().map(|r| r.len()).max().unwrap_or(0) as i32
    }
}

fn escape_xml_text(s: &str, out: &mut String) {
    for c in s.chars() {
        match c {
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '&' => out.push_str("&amp;"),
            '"' => out.push_str("&quot;"),
            '\'' => out.push_str("&#39;"),
            _ => out.push(c),
        }
    }
}

// Return true if character c at (r, c) should become a shape element (not text)
fn is_shape_char(c: char) -> bool {
    matches!(c, '-' | '|' | '/' | '\\' | '=' | '~' | '(' | ')')
}

fn render_shape(
    grid: &Grid,
    r: i32,
    c: i32,
    scale: f64,
    out: &mut String,
) {
    let ch = grid.get(r, c);
    let x0 = c * CELL_W;
    let y0 = r * CELL_H;
    let mid_x = x0 + CELL_W / 2;
    let mid_y = y0 + CELL_H / 2;
    let x1 = x0 + CELL_W;
    let y1 = y0 + CELL_H;

    fn emit_line(out: &mut String, scale: f64, x1: i32, y1: i32, x2: i32, y2: i32, class: &str) {
        out.push_str("  <line ");
        out.push_str("x1=\"");
        sn(x1).times(scale).write(out);
        out.push_str("\" y1=\"");
        sn(y1).times(scale).write(out);
        out.push_str("\" x2=\"");
        sn(x2).times(scale).write(out);
        out.push_str("\" y2=\"");
        sn(y2).times(scale).write(out);
        out.push_str("\" class=\"");
        out.push_str(class);
        out.push_str("\"></line>\n");
    }
    fn emit_path(out: &mut String, scale: f64, d: &str, class: &str) {
        out.push_str("  <path d=\"");
        out.push_str(d);
        out.push_str("\" class=\"");
        out.push_str(class);
        out.push_str("\"></path>\n");
    }
    let _ = (mid_x, mid_y, x1, y1, x0, y0);

    match ch {
        '-' => {
            emit_line(out, scale, x0, mid_y, x1, mid_y, "solid");
        }
        '~' => {
            emit_line(out, scale, x0, mid_y, x1, mid_y, "broken");
        }
        '=' => {
            emit_line(out, scale, x0, mid_y - 2, x1, mid_y - 2, "solid");
            emit_line(out, scale, x0, mid_y + 2, x1, mid_y + 2, "solid");
        }
        '|' => {
            emit_line(out, scale, mid_x, y0, mid_x, y1, "solid");
        }
        '/' => {
            emit_line(out, scale, x1, y0, x0, y1, "solid");
        }
        '\\' => {
            emit_line(out, scale, x0, y0, x1, y1, "solid");
        }
        '(' => {
            // arc open right: starts at top-right of cell, curves to bottom-right
            let mut d = String::new();
            write!(
                &mut d,
                "M {},{} A {},{} 0,0,0 {},{}",
                ((x1 as f64) * scale) as i64,
                ((y0 as f64) * scale) as i64,
                ((CELL_H as f64) * scale) as i64,
                ((CELL_H as f64) * scale) as i64,
                ((x1 as f64) * scale) as i64,
                ((y1 as f64) * scale) as i64,
            )
            .unwrap();
            emit_path(out, 1.0, &d, "nofill");
        }
        ')' => {
            let mut d = String::new();
            write!(
                &mut d,
                "M {},{} A {},{} 0,0,1 {},{}",
                ((x0 as f64) * scale) as i64,
                ((y0 as f64) * scale) as i64,
                ((CELL_H as f64) * scale) as i64,
                ((CELL_H as f64) * scale) as i64,
                ((x0 as f64) * scale) as i64,
                ((y1 as f64) * scale) as i64,
            )
            .unwrap();
            emit_path(out, 1.0, &d, "nofill");
        }
        _ => {}
    }
}

fn render_row_texts(grid: &Grid, r: i32, scale: f64, out: &mut String) {
    if r >= grid.num_rows() {
        return;
    }
    let row = &grid.rows[r as usize];
    let mut i = 0usize;
    while i < row.len() {
        let ch = row[i];
        if ch == ' ' || is_shape_char(ch) {
            i += 1;
            continue;
        }
        // start of a text run (of non-space, non-shape chars)
        let start = i;
        let mut buf = String::new();
        while i < row.len() && row[i] != ' ' && !is_shape_char(row[i]) {
            buf.push(row[i]);
            i += 1;
        }
        let x = (start as i32) * CELL_W + 2;
        let y = r * CELL_H + 12;
        out.push_str("  <text x=\"");
        sn(x).times(scale).write(out);
        out.push_str("\" y=\"");
        sn(y).times(scale).write(out);
        out.push_str("\" >");
        escape_xml_text(&buf, out);
        out.push_str("</text>\n");
    }
}

pub fn to_svg(input: &str, s: &Settings) -> String {
    let grid = Grid::from_str(input);
    let rows = grid.num_rows().max(1);
    let cols = grid.max_cols().max(1);

    let width_base = (cols + 1) * CELL_W;
    let height_base = (rows + 1) * CELL_H;
    let width = sn(width_base).times(s.scale);
    let height = sn(height_base).times(s.scale);

    let mut out = String::new();
    out.push_str("<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"");
    width.write(&mut out);
    out.push_str("\" height=\"");
    height.write(&mut out);
    out.push_str("\" class=\"svgbob\">\n");

    // Style block
    out.push_str("  <style>");
    out.push_str(".svgbob line, .svgbob path, .svgbob circle, .svgbob rect, .svgbob polygon {\n");
    out.push_str(&format!("  stroke: {};\n", s.stroke_color));
    // stroke-width formatting
    if (s.stroke_width - (s.stroke_width as i64) as f64).abs() < 1e-12 {
        out.push_str(&format!("  stroke-width: {};\n", s.stroke_width as i64));
    } else {
        out.push_str(&format!("  stroke-width: {};\n", s.stroke_width));
    }
    out.push_str("  stroke-opacity: 1;\n");
    out.push_str("  fill-opacity: 1;\n");
    out.push_str("  stroke-linecap: round;\n");
    out.push_str("  stroke-linejoin: miter;\n");
    out.push_str("}\n\n");

    out.push_str(".svgbob text {\n");
    out.push_str("  white-space: pre;\n");
    out.push_str("  fill: black;\n");
    out.push_str(&format!("  font-family: {};\n", s.font_family));
    out.push_str(&format!("  font-size: {}px;\n", s.font_size));
    out.push_str("}\n\n");

    out.push_str(".svgbob rect.backdrop {\n");
    out.push_str("  stroke: none;\n");
    out.push_str(&format!("  fill: {};\n", s.background));
    out.push_str("}\n\n");

    out.push_str(".svgbob .broken {\n");
    out.push_str("  stroke-dasharray: 8;\n");
    out.push_str("}\n\n");

    out.push_str(".svgbob .filled {\n");
    out.push_str(&format!("  fill: {};\n", s.fill_color));
    out.push_str("}\n\n");

    out.push_str(".svgbob .bg_filled {\n");
    out.push_str(&format!("  fill: {};\n", s.background));
    out.push_str("  stroke-width: 1;\n");
    out.push_str("}\n\n");

    out.push_str(".svgbob .nofill {\n");
    out.push_str(&format!("  fill: {};\n", s.background));
    out.push_str("}\n\n");

    for (name, marker) in &[
        ("arrow", "arrow"),
        ("arrow", "arrow"),
        ("diamond", "diamond"),
        ("diamond", "diamond"),
        ("circle", "circle"),
        ("circle", "circle"),
        ("open_circle", "open_circle"),
        ("open_circle", "open_circle"),
        ("big_open_circle", "big_open_circle"),
        ("big_open_circle", "big_open_circle"),
    ] {
        let _ = (name, marker);
    }
    // hardcode markers list
    let markers = [
        ("end_marked_arrow", "end", "arrow"),
        ("start_marked_arrow", "start", "arrow"),
        ("end_marked_diamond", "end", "diamond"),
        ("start_marked_diamond", "start", "diamond"),
        ("end_marked_circle", "end", "circle"),
        ("start_marked_circle", "start", "circle"),
        ("end_marked_open_circle", "end", "open_circle"),
        ("start_marked_open_circle", "start", "open_circle"),
        ("end_marked_big_open_circle", "end", "big_open_circle"),
        ("start_marked_big_open_circle", "start", "big_open_circle"),
    ];
    for (cls, pos, id) in markers.iter() {
        out.push_str(&format!(".svgbob .{} {{\n", cls));
        out.push_str(&format!("  marker-{}: url(#{});\n", pos, id));
        out.push_str("}\n\n");
    }

    out.push_str("</style>\n");

    // Defs
    out.push_str("  <defs>\n");
    out.push_str("    <marker id=\"arrow\" viewBox=\"-2 -2 8 8\" refX=\"4\" refY=\"2\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n");
    out.push_str("      <polygon points=\"0,0 0,4 4,2 0,0\"></polygon>\n");
    out.push_str("    </marker>\n");
    out.push_str("    <marker id=\"diamond\" viewBox=\"-2 -2 8 8\" refX=\"4\" refY=\"2\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n");
    out.push_str("      <polygon points=\"0,2 2,0 4,2 2,4 0,2\"></polygon>\n");
    out.push_str("    </marker>\n");
    out.push_str("    <marker id=\"circle\" viewBox=\"0 0 8 8\" refX=\"4\" refY=\"4\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n");
    out.push_str("      <circle cx=\"4\" cy=\"4\" r=\"2\" class=\"filled\"></circle>\n");
    out.push_str("    </marker>\n");
    out.push_str("    <marker id=\"open_circle\" viewBox=\"0 0 8 8\" refX=\"4\" refY=\"4\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n");
    out.push_str("      <circle cx=\"4\" cy=\"4\" r=\"2\" class=\"bg_filled\"></circle>\n");
    out.push_str("    </marker>\n");
    out.push_str("    <marker id=\"big_open_circle\" viewBox=\"0 0 8 8\" refX=\"4\" refY=\"4\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n");
    out.push_str("      <circle cx=\"4\" cy=\"4\" r=\"3\" class=\"bg_filled\"></circle>\n");
    out.push_str("    </marker>\n");
    out.push_str("  </defs>\n");

    // Backdrop rect
    out.push_str("  <rect class=\"backdrop\" x=\"0\" y=\"0\" width=\"");
    width.write(&mut out);
    out.push_str("\" height=\"");
    height.write(&mut out);
    out.push_str("\"></rect>\n");

    // Shapes then text, per row
    for r in 0..grid.num_rows() {
        let row_len = grid.rows[r as usize].len() as i32;
        for c in 0..row_len {
            let ch = grid.get(r, c);
            if is_shape_char(ch) {
                render_shape(&grid, r, c, s.scale, &mut out);
            }
        }
        render_row_texts(&grid, r, s.scale, &mut out);
    }

    out.push_str("</svg>\n");
    out
}
