const CELL_W: i32 = 8;
const CELL_H: i32 = 16;

#[derive(Clone, Copy)]
enum NumVal {
    Int(i32),
    Float(f64),
}

impl NumVal {
    fn times(self, s: f64) -> NumVal {
        match self {
            NumVal::Int(v) => {
                let r = (v as f64) * s;
                if (r.fract()).abs() < 1e-9 {
                    NumVal::Int(r.round() as i32)
                } else {
                    NumVal::Float(r)
                }
            }
            NumVal::Float(v) => NumVal::Float(v * s),
        }
    }
    fn write(self, out: &mut String) {
        match self {
            NumVal::Int(v) => {
                write!(out, "{}", v).unwrap();
            }
            NumVal::Float(v) => {
                if v.fract().abs() < 1e-9 {
                    write!(out, "{}", v.round() as i64).unwrap();
                } else {
                    write!(out, "{}", v).unwrap();
                }
            }
        }
    }
}

fn sn(v: i32) -> NumVal {
    NumVal::Int(v)
}

struct Grid {
    rows: Vec<Vec<char>>,
}

impl Grid {
    fn from_str(input: &str) -> Self {
        let rows: Vec<Vec<char>> = input.lines().map(|l| l.chars().collect()).collect();
        Grid { rows }
    }

    fn get(&self, r: i32, c: i32) -> char {
        if r < 0 || c < 0 {
            return ' ';
        }
        let r = r as usize;
        let c = c as usize;
        if r >= self.rows.len() {
            return ' ';
        }
        if c >= self.rows[r].len() {
            return ' ';
        }
        self.rows[r][c]
    }

    fn num_rows(&self) -> i32 {
        self.rows.len() as i32
    }

