// Guess the levenshtein-like suggestion for unrecognized subcommands.
// Original uses clap's suggestion mechanism. We approximate.
fn subcommand_suggestion(sub: &str) -> Option<&'static str> {
    let candidates = ["build", "help"];
    let mut best: Option<(&'static str, usize)> = None;
    for &cand in &candidates {
        let d = levenshtein(sub, cand);
        if d <= 3 {
            match best {
                None => best = Some((cand, d)),
                Some((_, bd)) if d < bd => best = Some((cand, d)),
                _ => {}
            }
        }
    }
    best.map(|(s, _)| s)
}

fn levenshtein(a: &str, b: &str) -> usize {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let (la, lb) = (a.len(), b.len());
    let mut dp = vec![vec![0usize; lb + 1]; la + 1];
    for i in 0..=la {
        dp[i][0] = i;
    }
    for j in 0..=lb {
        dp[0][j] = j;
    }
    for i in 1..=la {
        for j in 1..=lb {
            let cost = if a[i - 1] == b[j - 1] { 0 } else { 1 };
            dp[i][j] = (dp[i - 1][j] + 1)
                .min(dp[i][j - 1] + 1)
                .min(dp[i - 1][j - 1] + cost);
        }
    }
    dp[la][lb]
}

// usage_line computed based on flags+options seen so far
fn compute_usage(has_s: bool, seen_opts: &[&str]) -> String {
    // Reproduces clap 2.x pattern. If we haven't seen any args, default to full usage.
    if !has_s && seen_opts.is_empty() {
        return "executable [FLAGS] [OPTIONS] [input] [SUBCOMMAND]".to_string();
    }
    let mut parts: Vec<String> = Vec::new();
    parts.push("executable".to_string());
    if has_s {
        parts.push("-s".to_string());
    }
    // Options appear after -s sometimes? We'll preserve order of appearance.
    for o in seen_opts {
        parts.push(format!("--{} <{}>", o, o));
    }
    parts.join(" ")
}

struct Parsed {
    help: bool,
    version: bool,
    inline: bool, // -s flag
    settings: Settings,
    output: Option<String>,
    input: Option<String>,
    seen_opt_order: Vec<&'static str>,
}

enum ParseResult {
    Ok(Parsed),
    Subcommand(String, Vec<String>),
    Error(i32),
}

fn parse_main_args(args: &[String]) -> ParseResult {
    let mut p = Parsed {
        help: false,
        version: false,
        inline: false,
        settings: Settings::default(),
        output: None,
        input: None,
        seen_opt_order: Vec::new(),
    };

    let mut i = 0;
    let mut positional: Option<String> = None;
    let mut double_dash = false;

    while i < args.len() {
        let a = &args[i];
        if !double_dash {
            if a == "--" {
                double_dash = true;
                i += 1;
                continue;
            }
            if a == "--help" || a == "-h" {
                p.help = true;
                i += 1;
                continue;
            }
            if a == "--version" || a == "-V" {
                p.version = true;
                i += 1;
                continue;
            }
            if a == "-s" {
                p.inline = true;
                i += 1;
                continue;
            }
            // options with value
            if let Some(val) = option_val(a, "--background") {
                p.seen_opt_order.push("background");
                let v = get_value(val, args, &mut i);
                match v {
                    Some(vv) => p.settings.background = vv,
                    None => {
                        missing_arg_val("--background <background>", p.inline, &p.seen_opt_order);
                        return ParseResult::Error(1);
                    }
                }
                continue;
            }
            if let Some(val) = option_val(a, "--fill-color") {
                p.seen_opt_order.push("fill-color");
                let v = get_value(val, args, &mut i);
                match v {
                    Some(vv) => p.settings.fill_color = vv,
                    None => {
                        missing_arg_val("--fill-color <fill-color>", p.inline, &p.seen_opt_order);
                        return ParseResult::Error(1);
                    }
                }
                continue;
            }
            if let Some(val) = option_val(a, "--stroke-color") {
                p.seen_opt_order.push("stroke-color");
                let v = get_value(val, args, &mut i);
                match v {
                    Some(vv) => p.settings.stroke_color = vv,
                    None => {
                        missing_arg_val(
                            "--stroke-color <stroke-color>",
                            p.inline,
                            &p.seen_opt_order,
                        );
                        return ParseResult::Error(1);
                    }
                }
                continue;
            }
            if let Some(val) = option_val(a, "--font-family") {
                p.seen_opt_order.push("font-family");
                let v = get_value(val, args, &mut i);
                match v {
                    Some(vv) => p.settings.font_family = vv,
                    None => {
                        missing_arg_val("--font-family <font-family>", p.inline, &p.seen_opt_order);
                        return ParseResult::Error(1);
                    }
                }
                continue;
            }
            if let Some(val) = option_val(a, "--font-size") {
                p.seen_opt_order.push("font-size");
                let v = get_value(val, args, &mut i);
                match v {
                    Some(vv) => {
                        p.settings.font_size = vv.parse().unwrap_or(14);
                    }
                    None => {
                        missing_arg_val("--font-size <font-size>", p.inline, &p.seen_opt_order);
                        return ParseResult::Error(1);
                    }
                }
                continue;
            }
            if let Some(val) = option_val(a, "--scale") {
                p.seen_opt_order.push("scale");
                let v = get_value(val, args, &mut i);
                match v {
                    Some(vv) => {
                        p.settings.scale = vv.parse().unwrap_or(1.0);
                    }
                    None => {
                        missing_arg_val("--scale <scale>", p.inline, &p.seen_opt_order);
                        return ParseResult::Error(1);
                    }
                }
                continue;
            }
            if let Some(val) = option_val(a, "--stroke-width") {
                p.seen_opt_order.push("stroke-width");
                let v = get_value(val, args, &mut i);
                match v {
                    Some(vv) => {
                        p.settings.stroke_width = vv.parse().unwrap_or(2.0);
                    }
                    None => {
                        missing_arg_val(
                            "--stroke-width <stroke-width>",
                            p.inline,
                            &p.seen_opt_order,
                        );
                        return ParseResult::Error(1);
                    }
                }
                continue;
            }
            if a == "-o" || a == "--output" || a.starts_with("--output=") || a.starts_with("-o=") {
                let val: Option<&str> = if a == "-o" || a == "--output" {
                    None
                } else if let Some(v) = a.strip_prefix("--output=") {
                    Some(v)
                } else if let Some(v) = a.strip_prefix("-o=") {
                    Some(v)
                } else {
                    None
                };
                let v = get_value(val, args, &mut i);
                match v {
                    Some(vv) => p.output = Some(vv),
                    None => {
                        missing_arg_val("--output <output>", p.inline, &p.seen_opt_order);
                        return ParseResult::Error(1);
                    }
                }
                continue;
            }
            if a.starts_with("--") {
                // unknown option
                print_error_unexpected_arg(a, None);
                return ParseResult::Error(1);
            }
            if a.starts_with('-') && a != "-" {
                print_error_unexpected_arg(a, None);
                return ParseResult::Error(1);
            }
            // subcommand?
            if positional.is_none() {
                if a == "build" || a == "help" {
                    let sub_args: Vec<String> = args[i + 1..].to_vec();
                    return ParseResult::Subcommand(a.clone(), sub_args);
                }
                // Check if it looks like a subcommand
                if !p.inline && !looks_like_filename(a) {
                    // treat as unknown subcommand
                    print_unknown_subcommand(a, &p);
                    return ParseResult::Error(1);
                }
                positional = Some(a.clone());
                i += 1;
                continue;
            } else {
                // Second positional - treat as unknown
                print_error_unexpected_arg(a, None);
                return ParseResult::Error(1);
            }
        } else {
            // after --, everything positional
            if positional.is_none() {
                positional = Some(a.clone());
            } else {
                print_error_unexpected_arg(a, None);
                return ParseResult::Error(1);
            }
            i += 1;
        }
    }

    p.input = positional;
    ParseResult::Ok(p)
}

fn print_unknown_subcommand(sub: &str, p: &Parsed) {
    let suggestion = subcommand_suggestion(sub);
    eprintln!("error: The subcommand '{}' wasn't recognized", sub);
    if let Some(s) = suggestion {
        eprintln!("\tDid you mean '{}'?", s);
        eprintln!();
        eprintln!(
            "If you believe you received this message in error, try re-running with 'executable -- {}'",
            sub
        );
    }
    eprintln!();
    eprintln!("USAGE:");
    let usage = compute_usage(p.inline, &p.seen_opt_order);
    eprintln!("    {}", usage);
    eprintln!();
    eprintln!("For more information try --help");
}

fn option_val<'a>(arg: &'a str, name: &str) -> Option<Option<&'a str>> {
    if arg == name {
        return Some(None);
    }
    let prefix = format!("{}=", name);
    if let Some(v) = arg.strip_prefix(&prefix) {
        return Some(Some(v));
    }
    None
}

fn get_value(embedded: Option<&str>, args: &[String], i: &mut usize) -> Option<String> {
    match embedded {
        Some(v) => {
            *i += 1;
            Some(v.to_string())
        }
        None => {
            *i += 1;
            if *i < args.len() {
                let v = args[*i].clone();
                *i += 1;
                Some(v)
            } else {
                None
            }
        }
    }
}

