    eprintln!("    {}", desc);
    eprintln!();
    eprintln!("USAGE:");
    let mut u = compute_usage(has_s, seen);
    if !u.contains(desc) {
        u.push_str(" ");
        u.push_str(desc);
    }
    eprintln!("    {}", u);
    eprintln!();
    eprintln!("For more information try --help");
}

