fn glob_files(pattern: &str) -> Option<Vec<String>> {
    if pattern.is_empty() {
        return None;
    }
    // Split into dir + basename pattern
    let (dir_part, name_part) = match pattern.rfind('/') {
        Some(i) => (&pattern[..i], &pattern[i + 1..]),
        None => (".", pattern),
    };
    let dir = if dir_part.is_empty() { "." } else { dir_part };
    let entries = match fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => return None,
    };
    let mut results = Vec::new();
    for ent in entries.flatten() {
        let name = ent.file_name().to_string_lossy().to_string();
        if glob_match(name_part, &name) {
            let path_str = if dir == "." && !pattern.starts_with("./") {
                name.clone()
            } else {
                format!("{}/{}", dir, name)
            };
            results.push(path_str);
        }
    }
    results.sort();
    Some(results)
}

fn glob_match(pat: &str, name: &str) -> bool {
    // Simple glob: *, ?
    let p: Vec<char> = pat.chars().collect();
    let n: Vec<char> = name.chars().collect();
    glob_match_r(&p, 0, &n, 0)
}

fn glob_match_r(p: &[char], pi: usize, n: &[char], ni: usize) -> bool {
    if pi == p.len() {
        return ni == n.len();
    }
    match p[pi] {
        '*' => {
            // zero or more
            if glob_match_r(p, pi + 1, n, ni) {
                return true;
            }
            if ni < n.len() && glob_match_r(p, pi, n, ni + 1) {
                return true;
            }
            false
        }
        '?' => {
            if ni >= n.len() {
                false
            } else {
                glob_match_r(p, pi + 1, n, ni + 1)
            }
        }
        c => {
            if ni < n.len() && n[ni] == c {
                glob_match_r(p, pi + 1, n, ni + 1)
            } else {
                false
            }
        }
    }
}

fn run_help_sub(args: &[String]) -> ExitCode {
    if args.is_empty() {
