fn option_val<'a>(arg: &'a str, name: &str) -> Option<Option<&'a str>> {
    if arg == name {
        return Some(None);
    }
    let prefix = format!("{}=", name);
    if let Some(v) = arg.strip_prefix(&prefix) {
        return Some(Some(v));
    }
    None
}

fn get_value(embedded: Option<&str>, args: &[String], i: &mut usize) -> Option<String> {
    match embedded {
        Some(v) => {
            *i += 1;
            Some(v.to_string())
        }
        None => {
            *i += 1;
            if *i < args.len() {
                let v = args[*i].clone();
                *i += 1;
                Some(v)
            } else {
