// Guess the levenshtein-like suggestion for unrecognized subcommands.
// Original uses clap's suggestion mechanism. We approximate.
fn subcommand_suggestion(sub: &str) -> Option<&'static str> {
    let candidates = ["build", "help"];
    let mut best: Option<(&'static str, usize)> = None;
    for &cand in &candidates {
        let d = levenshtein(sub, cand);
        if d <= 3 {
            match best {
                None => best = Some((cand, d)),
                Some((_, bd)) if d < bd => best = Some((cand, d)),
                _ => {}
            }
        }
    }
    best.map(|(s, _)| s)
}

fn levenshtein(a: &str, b: &str) -> usize {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let (la, lb) = (a.len(), b.len());
    let mut dp = vec![vec![0usize; lb + 1]; la + 1];
    for i in 0..=la {
        dp[i][0] = i;
    }
    for j in 0..=lb {
        dp[0][j] = j;
    }
    for i in 1..=la {
        for j in 1..=lb {
            let cost = if a[i - 1] == b[j - 1] { 0 } else { 1 };
            dp[i][j] = (dp[i - 1][j] + 1)
                .min(dp[i][j - 1] + 1)
                .min(dp[i - 1][j - 1] + cost);
        }
    }
    dp[la][lb]
}

// usage_line computed based on flags+options seen so far
fn compute_usage(has_s: bool, seen_opts: &[&str]) -> String {
    // Reproduces clap 2.x pattern. If we haven't seen any args, default to full usage.
    if !has_s && seen_opts.is_empty() {
        return "executable [FLAGS] [OPTIONS] [input] [SUBCOMMAND]".to_string();
    }
    let mut parts: Vec<String> = Vec::new();
    parts.push("executable".to_string());
    if has_s {
        parts.push("-s".to_string());
    }
    // Options appear after -s sometimes? We'll preserve order of appearance.
    for o in seen_opts {
        parts.push(format!("--{} <{}>", o, o));
    }
    parts.join(" ")
}

