    ParseResult::Ok(p)
}

fn print_unknown_subcommand(sub: &str, p: &Parsed) {
    let suggestion = subcommand_suggestion(sub);
    eprintln!("error: The subcommand '{}' wasn't recognized", sub);
    if let Some(s) = suggestion {
        eprintln!("\tDid you mean '{}'?", s);
        eprintln!();
        eprintln!(
            "If you believe you received this message in error, try re-running with 'executable -- {}'",
            sub
        );
    }
    eprintln!();
    eprintln!("USAGE:");
    let usage = compute_usage(p.inline, &p.seen_opt_order);
    eprintln!("    {}", usage);
    eprintln!();
    eprintln!("For more information try --help");
}

fn option_val<'a>(arg: &'a str, name: &str) -> Option<Option<&'a str>> {
    if arg == name {
        return Some(None);
    }
    let prefix = format!("{}=", name);
    if let Some(v) = arg.strip_prefix(&prefix) {
        return Some(Some(v));
    }
    None
}

fn get_value(embedded: Option<&str>, args: &[String], i: &mut usize) -> Option<String> {
    match embedded {
        Some(v) => {
            *i += 1;
            Some(v.to_string())
        }
        None => {
            *i += 1;
            if *i < args.len() {
                let v = args[*i].clone();
                *i += 1;
                Some(v)
            } else {
                None
            }
        }
    }
}

fn missing_arg_val(desc: &str, has_s: bool, seen: &[&str]) {
    eprintln!("error: The following required arguments were not provided:");
    eprintln!("    {}", desc);
    eprintln!();
    eprintln!("USAGE:");
    let mut u = compute_usage(has_s, seen);
    if !u.contains(desc) {
        u.push_str(" ");
        u.push_str(desc);
    }
    eprintln!("    {}", u);
    eprintln!();
    eprintln!("For more information try --help");
}

fn looks_like_filename(s: &str) -> bool {
    s.contains('/')
        || s.contains('.')
        || s.contains('\\')
        || Path::new(s).exists()
}

fn run_build(args: &[String]) -> ExitCode {
    // Parse build arguments: -i/--input, -o/--outdir, -h/--help, -V/--version
    let mut input: Option<String> = None;
    let mut outdir: Option<String> = None;
    let mut help = false;
    let mut version = false;

    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        if a == "-h" || a == "--help" {
            help = true;
            i += 1;
            continue;
        }
        if a == "-V" || a == "--version" {
            version = true;
            i += 1;
            continue;
        }
        if a == "-i" || a == "--input" {
            if i + 1 < args.len() {
                input = Some(args[i + 1].clone());
                i += 2;
                continue;
            } else {
                eprintln!("error: The following required arguments were not provided:");
                eprintln!("    --input <input>");
                eprintln!();
                eprintln!("USAGE:");
                eprintln!("    executable build --input <input>");
                eprintln!();
                eprintln!("For more information try --help");
                return ExitCode::from(1);
            }
        }
        if let Some(v) = a.strip_prefix("--input=") {
            input = Some(v.to_string());
            i += 1;
            continue;
        }
        if let Some(v) = a.strip_prefix("-i=") {
            input = Some(v.to_string());
            i += 1;
            continue;
        }
        if a == "-o" || a == "--outdir" {
            if i + 1 < args.len() {
                outdir = Some(args[i + 1].clone());
                i += 2;
                continue;
            } else {
                eprintln!("error: The following required arguments were not provided:");
                eprintln!("    --outdir <outdir>");
                eprintln!();
                eprintln!("USAGE:");
                eprintln!("    executable build --outdir <outdir>");
                eprintln!();
                eprintln!("For more information try --help");
                return ExitCode::from(1);
            }
        }
        if let Some(v) = a.strip_prefix("--outdir=") {
            outdir = Some(v.to_string());
            i += 1;
            continue;
        }
        if let Some(v) = a.strip_prefix("-o=") {
            outdir = Some(v.to_string());
            i += 1;
            continue;
        }
        // unknown
        print_error_unexpected_arg(a, Some("build"));
        return ExitCode::from(1);
    }

    if help {
        println!("{}", build_help());
        return ExitCode::from(0);
    }
    if version {
        println!("executable-build 0.0.1");
        return ExitCode::from(0);
    }

    // run batch
    let pattern = input.unwrap_or_default();
    let outdir_str = outdir.clone().unwrap_or_default();

    let files = match glob_files(&pattern) {
        Some(v) => v,
        None => {
            println!("[Error]: No such dir name is {} !", pattern);
            return ExitCode::from(1);
        }
    };

    if files.is_empty() {
        println!("[Error]: No such dir name is {} !", pattern);
        return ExitCode::from(1);
    }

    for f in files {
        let fname = Path::new(&f)
            .file_stem()
            .map(|s| s.to_string_lossy().to_string())
            .unwrap_or_default();
        let out_path = if outdir_str.is_empty() {
            // place next to input
            let parent = Path::new(&f).parent().unwrap_or(Path::new("."));
            parent.join(format!("{}.svg", fname))
        } else {
            PathBuf::from(&outdir_str).join(format!("{}.svg", fname))
        };
        println!("{} => {}", f, out_path.display());
        if let Ok(content) = fs::read_to_string(&f) {
            let settings = Settings::default();
            let svg = to_svg(&content, &settings);
            let _ = fs::write(&out_path, svg);
        }
    }
    ExitCode::from(1)
}

fn glob_files(pattern: &str) -> Option<Vec<String>> {
    if pattern.is_empty() {
        return None;
    }
    // Split into dir + basename pattern
    let (dir_part, name_part) = match pattern.rfind('/') {
        Some(i) => (&pattern[..i], &pattern[i + 1..]),
        None => (".", pattern),
    };
    let dir = if dir_part.is_empty() { "." } else { dir_part };
    let entries = match fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => return None,
    };
    let mut results = Vec::new();
    for ent in entries.flatten() {
        let name = ent.file_name().to_string_lossy().to_string();
        if glob_match(name_part, &name) {
            let path_str = if dir == "." && !pattern.starts_with("./") {
                name.clone()
            } else {
                format!("{}/{}", dir, name)
            };
            results.push(path_str);
        }
    }
    results.sort();
    Some(results)
}

fn glob_match(pat: &str, name: &str) -> bool {
    // Simple glob: *, ?
    let p: Vec<char> = pat.chars().collect();
    let n: Vec<char> = name.chars().collect();
    glob_match_r(&p, 0, &n, 0)
}

fn glob_match_r(p: &[char], pi: usize, n: &[char], ni: usize) -> bool {
    if pi == p.len() {
        return ni == n.len();
    }
    match p[pi] {
        '*' => {
            // zero or more
            if glob_match_r(p, pi + 1, n, ni) {
                return true;
            }
            if ni < n.len() && glob_match_r(p, pi, n, ni + 1) {
                return true;
            }
            false
        }
        '?' => {
            if ni >= n.len() {
                false
            } else {
                glob_match_r(p, pi + 1, n, ni + 1)
            }
        }
        c => {
            if ni < n.len() && n[ni] == c {
                glob_match_r(p, pi + 1, n, ni + 1)
            } else {
                false
            }
        }
    }
}

fn run_help_sub(args: &[String]) -> ExitCode {
    if args.is_empty() {
        println!("{}", root_help());
        return ExitCode::from(0);
    }
    let sub = &args[0];
    match sub.as_str() {
        "build" => {
            println!("{}", build_help());
            ExitCode::from(0)
        }
        "help" => {
            println!("{}", help_help());
            ExitCode::from(0)
        }
        _ => {
            eprintln!("error: The subcommand '{}' wasn't recognized", sub);
            eprintln!();
            eprintln!("USAGE:");
            eprintln!("\texecutable help <subcommands>...");
            eprintln!();
            eprintln!("For more information try --help");
            ExitCode::from(1)
        }
    }
}

fn main() -> ExitCode {
    let args: Vec<String> = env::args().skip(1).collect();

    let parsed = parse_main_args(&args);
    match parsed {
        ParseResult::Error(code) => return ExitCode::from(code as u8),
        ParseResult::Subcommand(name, sub_args) => match name.as_str() {
            "build" => return run_build(&sub_args),
            "help" => return run_help_sub(&sub_args),
            _ => return ExitCode::from(1),
        },
        ParseResult::Ok(p) => {
            if p.help {
                println!("{}", root_help());
                return ExitCode::from(0);
            }
            if p.version {
                println!("svgbob 0.7.6");
                return ExitCode::from(0);
            }

            // Get input content
            let content = if p.inline {
                // -s: positional is treated as inline string
                match p.input.as_ref() {
                    Some(s) => s.clone(),
                    None => {
                        eprintln!();
                        panic!("called `Option::unwrap()` on a `None` value");
                    }
                }
            } else if let Some(path) = p.input.as_ref() {
                match fs::read_to_string(path) {
                    Ok(s) => s,
                    Err(e) => {
                        eprintln!("Failed to open input file {}: {}", path, e);
                        return ExitCode::from(1);
                    }
                }
            } else {
                let mut s = String::new();
                let _ = io::stdin().read_to_string(&mut s);
                s
            };

            let svg = to_svg(&content, &p.settings);
            if let Some(out_path) = p.output {
                if let Err(e) = fs::write(&out_path, svg) {
                    eprintln!("Failed to write output: {}", e);
                    return ExitCode::from(1);
                }
            } else {
                let _ = io::stdout().write_all(svg.as_bytes());
            }
            ExitCode::from(0)
        }
    }

    // unreachable
    #[allow(unreachable_code)]
    ExitCode::from(0)
}
