// svgbob: ASCII art to SVG renderer
// Reimplementation from observed behavior.

use std::fmt::Write;

pub struct Settings {
    pub font_family: String,
    pub font_size: i32,
    pub background: String,
    pub fill_color: String,
    pub stroke_color: String,
    pub stroke_width: f64,
    pub scale: f64,
}

impl Default for Settings {
    fn default() -> Self {
        Self {
            font_family: "Iosevka Fixed, monospace".to_string(),
            font_size: 14,
            background: "white".to_string(),
            fill_color: "black".to_string(),
            stroke_color: "black".to_string(),
            stroke_width: 2.0,
            scale: 1.0,
        }
    }
}

const CELL_W: i32 = 8;
const CELL_H: i32 = 16;

// Represent an integer coordinate that needs scaling.
fn fmt_scaled(v: i32, scale: f64, out: &mut String) {
    if (scale - 1.0).abs() < 1e-12 {
        write!(out, "{}", v).unwrap();
        return;
    }
    let r = (v as f64) * scale;
    if (r.fract()).abs() < 1e-9 {
        write!(out, "{}", r.round() as i64).unwrap();
    } else {
        write!(out, "{}", r).unwrap();
    }
}

struct Grid {
    rows: Vec<Vec<char>>,
}

impl Grid {
    fn from_str(input: &str) -> Self {
        let rows: Vec<Vec<char>> = input.lines().map(|l| l.chars().collect()).collect();
        Grid { rows }
    }

    fn get(&self, r: i32, c: i32) -> char {
        if r < 0 || c < 0 {
            return ' ';
        }
        let r = r as usize;
        let c = c as usize;
        if r >= self.rows.len() {
            return ' ';
        }
        if c >= self.rows[r].len() {
            return ' ';
        }
        self.rows[r][c]
    }

    fn num_rows(&self) -> i32 {
        self.rows.len() as i32
    }

    fn max_cols(&self) -> i32 {
        self.rows.iter().map(|r| r.len()).max().unwrap_or(0) as i32
    }

    fn row_len(&self, r: i32) -> i32 {
        if r < 0 || (r as usize) >= self.rows.len() {
            0
        } else {
            self.rows[r as usize].len() as i32
        }
    }
}

fn escape_xml_text(s: &str, out: &mut String) {
    for c in s.chars() {
        match c {
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '&' => out.push_str("&amp;"),
            '"' => out.push_str("&quot;"),
            '\'' => out.push_str("&#39;"),
            _ => out.push(c),
        }
    }
}

/// Shape characters that are never rendered as text (if they form a pattern).
fn is_basic_shape_char(c: char) -> bool {
    matches!(c, '-' | '|' | '/' | '\\' | '=' | '~' | '(' | ')')
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum CellState {
    Text,   // rendered as part of text
    Shape,  // rendered as part of shape
    Space,  // empty
}

/// Decide for each cell whether it's part of a shape or text.
fn classify(grid: &Grid) -> Vec<Vec<CellState>> {
    let nrows = grid.num_rows() as usize;
    let mut result: Vec<Vec<CellState>> = Vec::with_capacity(nrows);
    for r in 0..nrows {
        let row_len = grid.rows[r].len();
        let mut row_state = vec![CellState::Space; row_len];
        for c in 0..row_len {
            let ch = grid.rows[r][c];
            if ch == ' ' {
                row_state[c] = CellState::Space;
            } else if is_basic_shape_char(ch) {
                row_state[c] = CellState::Shape;
            } else {
                row_state[c] = CellState::Text;
            }
        }
        result.push(row_state);
    }
    result
}

fn emit_line(out: &mut String, scale: f64, x1: i32, y1: i32, x2: i32, y2: i32, class: &str) {
    out.push_str("  <line x1=\"");
    fmt_scaled(x1, scale, out);
    out.push_str("\" y1=\"");
    fmt_scaled(y1, scale, out);
    out.push_str("\" x2=\"");
    fmt_scaled(x2, scale, out);
    out.push_str("\" y2=\"");
    fmt_scaled(y2, scale, out);
    out.push_str("\" class=\"");
    out.push_str(class);
    out.push_str("\"></line>\n");
}

fn emit_path(out: &mut String, scale: f64, d: &str, class: &str) {
    // d has integer coordinates; parse and scale
    out.push_str("  <path d=\"");
    out.push_str(d);
    out.push_str("\" class=\"");
    out.push_str(class);
    out.push_str("\"></path>\n");
    let _ = scale;
}

fn emit_horizontal_run(
    out: &mut String,
    scale: f64,
    r: i32,
    c_start: i32,
    c_end_inclusive: i32,
    class: &str,
    double: bool,
) {
    let x1 = c_start * CELL_W;
    let x2 = (c_end_inclusive + 1) * CELL_W;
    let y = r * CELL_H + CELL_H / 2;
    if double {
        emit_line(out, scale, x1, y - 2, x2, y - 2, class);
        emit_line(out, scale, x1, y + 2, x2, y + 2, class);
    } else {
        emit_line(out, scale, x1, y, x2, y, class);
    }
}

fn emit_vertical_run(
    out: &mut String,
    scale: f64,
    r_start: i32,
    r_end_inclusive: i32,
    c: i32,
    class: &str,
) {
    let x = c * CELL_W + CELL_W / 2;
    let y1 = r_start * CELL_H;
    let y2 = (r_end_inclusive + 1) * CELL_H;
    emit_line(out, scale, x, y1, x, y2, class);
}

fn render_shapes(grid: &Grid, scale: f64, out: &mut String) {
    let nrows = grid.num_rows();

    // Horizontal lines: merge consecutive same-char runs of '-' '=' '~'
    for r in 0..nrows {
        let row_len = grid.row_len(r);
        let mut c = 0;
        while c < row_len {
            let ch = grid.get(r, c);
            if ch == '-' || ch == '=' || ch == '~' {
                let run_ch = ch;
                let start = c;
                while c < row_len && grid.get(r, c) == run_ch {
                    c += 1;
                }
                let end = c - 1;
                let (class, double) = match run_ch {
                    '-' => ("solid", false),
                    '=' => ("solid", true),
                    '~' => ("broken", false),
                    _ => ("solid", false),
                };
                emit_horizontal_run(out, scale, r, start, end, class, double);
            } else {
                c += 1;
            }
        }
    }

    // Vertical lines: merge consecutive '|' in same column
    if nrows > 0 {
        let max_cols = grid.max_cols();
        for c in 0..max_cols {
            let mut r = 0;
            while r < nrows {
                if grid.get(r, c) == '|' {
                    let start = r;
                    while r < nrows && grid.get(r, c) == '|' {
                        r += 1;
                    }
                    let end = r - 1;
                    emit_vertical_run(out, scale, start, end, c, "solid");
                } else {
                    r += 1;
                }
            }
        }
    }

    // Diagonals / and \: one per cell (no merging for now)
    for r in 0..nrows {
        let row_len = grid.row_len(r);
        for c in 0..row_len {
            let ch = grid.get(r, c);
            let x0 = c * CELL_W;
            let y0 = r * CELL_H;
            let x1 = x0 + CELL_W;
            let y1 = y0 + CELL_H;
