                '/' => emit_line(out, scale, x1, y0, x0, y1, "solid"),
                '\\' => emit_line(out, scale, x0, y0, x1, y1, "solid"),
                '(' => {
                    let mut d = String::new();
                    let sc = |v: i32| {
                        let rr = (v as f64) * scale;
                        if (rr.fract()).abs() < 1e-9 {
                            format!("{}", rr.round() as i64)
                        } else {
                            format!("{}", rr)
                        }
                    };
                    write!(
                        &mut d,
                        "M {},{} A {},{} 0,0,0 {},{}",
                        sc(x1),
                        sc(y0),
                        sc(CELL_H),
                        sc(CELL_H),
                        sc(x1),
                        sc(y1),
                    )
                    .unwrap();
                    emit_path(out, scale, &d, "nofill");
                }
                ')' => {
                    let mut d = String::new();
                    let sc = |v: i32| {
                        let rr = (v as f64) * scale;
                        if (rr.fract()).abs() < 1e-9 {
                            format!("{}", rr.round() as i64)
                        } else {
                            format!("{}", rr)
                        }
                    };
                    write!(
                        &mut d,
                        "M {},{} A {},{} 0,0,1 {},{}",
                        sc(x0),
                        sc(y0),
                        sc(CELL_H),
                        sc(CELL_H),
                        sc(x0),
                        sc(y1),
                    )
                    .unwrap();
                    emit_path(out, scale, &d, "nofill");
                }
                _ => {}
            }
        }
    }
}

fn render_row_texts(grid: &Grid, classified: &[Vec<CellState>], r: i32, scale: f64, out: &mut String) {
    if r >= grid.num_rows() {
        return;
    }
    let row = &grid.rows[r as usize];
    let states = &classified[r as usize];
    let mut i = 0usize;
    while i < row.len() {
        if states[i] != CellState::Text {
            i += 1;
            continue;
        }
        let start = i;
        let mut buf = String::new();
        while i < row.len() && states[i] == CellState::Text {
            buf.push(row[i]);
            i += 1;
        }
        let x = (start as i32) * CELL_W + 2;
        let y = r * CELL_H + 12;
        out.push_str("  <text x=\"");
        fmt_scaled(x, scale, out);
        out.push_str("\" y=\"");
        fmt_scaled(y, scale, out);
        out.push_str("\" >");
        escape_xml_text(&buf, out);
        out.push_str("</text>\n");
    }
}

