        self.rows.len() as i32
    }

    fn max_cols(&self) -> i32 {
        self.rows.iter().map(|r| r.len()).max().unwrap_or(0) as i32
    }

    fn row_len(&self, r: i32) -> i32 {
        if r < 0 || (r as usize) >= self.rows.len() {
            0
        } else {
            self.rows[r as usize].len() as i32
        }
    }
}

fn escape_xml_text(s: &str, out: &mut String) {
    for c in s.chars() {
        match c {
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '&' => out.push_str("&amp;"),
            '"' => out.push_str("&quot;"),
            '\'' => out.push_str("&#39;"),
            _ => out.push(c),
        }
    }
}

/// Shape characters that are never rendered as text (if they form a pattern).
fn is_basic_shape_char(c: char) -> bool {
    matches!(c, '-' | '|' | '/' | '\\' | '=' | '~' | '(' | ')')
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum CellState {
    Text,   // rendered as part of text
    Shape,  // rendered as part of shape
    Space,  // empty
}

/// Decide for each cell whether it's part of a shape or text.
fn classify(grid: &Grid) -> Vec<Vec<CellState>> {
    let nrows = grid.num_rows() as usize;
    let mut result: Vec<Vec<CellState>> = Vec::with_capacity(nrows);
    for r in 0..nrows {
        let row_len = grid.rows[r].len();
        let mut row_state = vec![CellState::Space; row_len];
        for c in 0..row_len {
            let ch = grid.rows[r][c];
            if ch == ' ' {
                row_state[c] = CellState::Space;
            } else if is_basic_shape_char(ch) {
                row_state[c] = CellState::Shape;
            } else {
                row_state[c] = CellState::Text;
            }
        }
        result.push(row_state);
    }
    result
}

fn emit_line(out: &mut String, scale: f64, x1: i32, y1: i32, x2: i32, y2: i32, class: &str) {
    out.push_str("  <line x1=\"");
    fmt_scaled(x1, scale, out);
    out.push_str("\" y1=\"");
    fmt_scaled(y1, scale, out);
    out.push_str("\" x2=\"");
    fmt_scaled(x2, scale, out);
    out.push_str("\" y2=\"");
    fmt_scaled(y2, scale, out);
    out.push_str("\" class=\"");
    out.push_str(class);
    out.push_str("\"></line>\n");
}

fn emit_path(out: &mut String, scale: f64, d: &str, class: &str) {
    // d has integer coordinates; parse and scale
    out.push_str("  <path d=\"");
    out.push_str(d);
    out.push_str("\" class=\"");
    out.push_str(class);
    out.push_str("\"></path>\n");
    let _ = scale;
}

fn emit_horizontal_run(
    out: &mut String,
    scale: f64,
    r: i32,
    c_start: i32,
    c_end_inclusive: i32,
    class: &str,
    double: bool,
) {
    let x1 = c_start * CELL_W;
    let x2 = (c_end_inclusive + 1) * CELL_W;
    let y = r * CELL_H + CELL_H / 2;
    if double {
        emit_line(out, scale, x1, y - 2, x2, y - 2, class);
        emit_line(out, scale, x1, y + 2, x2, y + 2, class);
    } else {
        emit_line(out, scale, x1, y, x2, y, class);
    }
}

fn emit_vertical_run(
    out: &mut String,
    scale: f64,
    r_start: i32,
    r_end_inclusive: i32,
    c: i32,
    class: &str,
) {
    let x = c * CELL_W + CELL_W / 2;
    let y1 = r_start * CELL_H;
    let y2 = (r_end_inclusive + 1) * CELL_H;
    emit_line(out, scale, x, y1, x, y2, class);
}

fn render_shapes(grid: &Grid, scale: f64, out: &mut String) {
    let nrows = grid.num_rows();

    // Horizontal lines: merge consecutive same-char runs of '-' '=' '~'
    for r in 0..nrows {
        let row_len = grid.row_len(r);
        let mut c = 0;
        while c < row_len {
            let ch = grid.get(r, c);
            if ch == '-' || ch == '=' || ch == '~' {
                let run_ch = ch;
                let start = c;
                while c < row_len && grid.get(r, c) == run_ch {
                    c += 1;
                }
                let end = c - 1;
                let (class, double) = match run_ch {
                    '-' => ("solid", false),
                    '=' => ("solid", true),
                    '~' => ("broken", false),
                    _ => ("solid", false),
                };
                emit_horizontal_run(out, scale, r, start, end, class, double);
            } else {
                c += 1;
            }
        }
    }

    // Vertical lines: merge consecutive '|' in same column
    if nrows > 0 {
        let max_cols = grid.max_cols();
        for c in 0..max_cols {
            let mut r = 0;
            while r < nrows {
                if grid.get(r, c) == '|' {
                    let start = r;
                    while r < nrows && grid.get(r, c) == '|' {
                        r += 1;
                    }
                    let end = r - 1;
                    emit_vertical_run(out, scale, start, end, c, "solid");
                } else {
                    r += 1;
                }
            }
        }
    }

    // Diagonals / and \: one per cell (no merging for now)
    for r in 0..nrows {
        let row_len = grid.row_len(r);
        for c in 0..row_len {
            let ch = grid.get(r, c);
            let x0 = c * CELL_W;
            let y0 = r * CELL_H;
            let x1 = x0 + CELL_W;
            let y1 = y0 + CELL_H;
            match ch {
                '/' => emit_line(out, scale, x1, y0, x0, y1, "solid"),
                '\\' => emit_line(out, scale, x0, y0, x1, y1, "solid"),
                '(' => {
                    let mut d = String::new();
                    let sc = |v: i32| {
                        let rr = (v as f64) * scale;
                        if (rr.fract()).abs() < 1e-9 {
                            format!("{}", rr.round() as i64)
                        } else {
                            format!("{}", rr)
                        }
                    };
                    write!(
                        &mut d,
                        "M {},{} A {},{} 0,0,0 {},{}",
                        sc(x1),
                        sc(y0),
                        sc(CELL_H),
                        sc(CELL_H),
                        sc(x1),
                        sc(y1),
                    )
                    .unwrap();
                    emit_path(out, scale, &d, "nofill");
                }
                ')' => {
                    let mut d = String::new();
                    let sc = |v: i32| {
                        let rr = (v as f64) * scale;
                        if (rr.fract()).abs() < 1e-9 {
                            format!("{}", rr.round() as i64)
                        } else {
                            format!("{}", rr)
                        }
                    };
                    write!(
                        &mut d,
                        "M {},{} A {},{} 0,0,1 {},{}",
                        sc(x0),
                        sc(y0),
                        sc(CELL_H),
                        sc(CELL_H),
                        sc(x0),
                        sc(y1),
                    )
                    .unwrap();
                    emit_path(out, scale, &d, "nofill");
                }
                _ => {}
            }
        }
    }
}

fn render_row_texts(grid: &Grid, classified: &[Vec<CellState>], r: i32, scale: f64, out: &mut String) {
    if r >= grid.num_rows() {
        return;
    }
    let row = &grid.rows[r as usize];
    let states = &classified[r as usize];
    let mut i = 0usize;
    while i < row.len() {
        if states[i] != CellState::Text {
            i += 1;
            continue;
        }
        let start = i;
        let mut buf = String::new();
        while i < row.len() && states[i] == CellState::Text {
            buf.push(row[i]);
            i += 1;
        }
        let x = (start as i32) * CELL_W + 2;
        let y = r * CELL_H + 12;
        out.push_str("  <text x=\"");
        fmt_scaled(x, scale, out);
        out.push_str("\" y=\"");
        fmt_scaled(y, scale, out);
        out.push_str("\" >");
        escape_xml_text(&buf, out);
        out.push_str("</text>\n");
    }
}

pub fn to_svg(input: &str, s: &Settings) -> String {
    let grid = Grid::from_str(input);
    let rows = grid.num_rows().max(1);
    let cols = grid.max_cols().max(1);

    let width_base = (cols + 1) * CELL_W;
    let height_base = (rows + 1) * CELL_H;

    let mut out = String::new();
    out.push_str("<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"");
    fmt_scaled(width_base, s.scale, &mut out);
    out.push_str("\" height=\"");
    fmt_scaled(height_base, s.scale, &mut out);
    out.push_str("\" class=\"svgbob\">\n");

    // Style block
    out.push_str("  <style>");
    out.push_str(".svgbob line, .svgbob path, .svgbob circle, .svgbob rect, .svgbob polygon {\n");
    out.push_str(&format!("  stroke: {};\n", s.stroke_color));
    if (s.stroke_width - (s.stroke_width as i64) as f64).abs() < 1e-12 {
        out.push_str(&format!("  stroke-width: {};\n", s.stroke_width as i64));
    } else {
        out.push_str(&format!("  stroke-width: {};\n", s.stroke_width));
    }
    out.push_str("  stroke-opacity: 1;\n");
    out.push_str("  fill-opacity: 1;\n");
    out.push_str("  stroke-linecap: round;\n");
    out.push_str("  stroke-linejoin: miter;\n");
    out.push_str("}\n\n");

    out.push_str(".svgbob text {\n");
    out.push_str("  white-space: pre;\n");
    out.push_str("  fill: black;\n");
    out.push_str(&format!("  font-family: {};\n", s.font_family));
    out.push_str(&format!("  font-size: {}px;\n", s.font_size));
    out.push_str("}\n\n");

    out.push_str(".svgbob rect.backdrop {\n");
    out.push_str("  stroke: none;\n");
    out.push_str(&format!("  fill: {};\n", s.background));
    out.push_str("}\n\n");

    out.push_str(".svgbob .broken {\n");
    out.push_str("  stroke-dasharray: 8;\n");
    out.push_str("}\n\n");

    out.push_str(".svgbob .filled {\n");
    out.push_str(&format!("  fill: {};\n", s.fill_color));
    out.push_str("}\n\n");

    out.push_str(".svgbob .bg_filled {\n");
    out.push_str(&format!("  fill: {};\n", s.background));
    out.push_str("  stroke-width: 1;\n");
    out.push_str("}\n\n");

    out.push_str(".svgbob .nofill {\n");
    out.push_str(&format!("  fill: {};\n", s.background));
    out.push_str("}\n\n");

    let markers = [
        ("end_marked_arrow", "end", "arrow"),
        ("start_marked_arrow", "start", "arrow"),
        ("end_marked_diamond", "end", "diamond"),
        ("start_marked_diamond", "start", "diamond"),
        ("end_marked_circle", "end", "circle"),
        ("start_marked_circle", "start", "circle"),
        ("end_marked_open_circle", "end", "open_circle"),
        ("start_marked_open_circle", "start", "open_circle"),
        ("end_marked_big_open_circle", "end", "big_open_circle"),
        ("start_marked_big_open_circle", "start", "big_open_circle"),
    ];
    for (cls, pos, id) in markers.iter() {
        out.push_str(&format!(".svgbob .{} {{\n", cls));
        out.push_str(&format!("  marker-{}: url(#{});\n", pos, id));
        out.push_str("}\n\n");
    }

    out.push_str("</style>\n");

    // Defs
    out.push_str("  <defs>\n");
    out.push_str("    <marker id=\"arrow\" viewBox=\"-2 -2 8 8\" refX=\"4\" refY=\"2\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n");
    out.push_str("      <polygon points=\"0,0 0,4 4,2 0,0\"></polygon>\n");
    out.push_str("    </marker>\n");
    out.push_str("    <marker id=\"diamond\" viewBox=\"-2 -2 8 8\" refX=\"4\" refY=\"2\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n");
    out.push_str("      <polygon points=\"0,2 2,0 4,2 2,4 0,2\"></polygon>\n");
    out.push_str("    </marker>\n");
    out.push_str("    <marker id=\"circle\" viewBox=\"0 0 8 8\" refX=\"4\" refY=\"4\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n");
    out.push_str("      <circle cx=\"4\" cy=\"4\" r=\"2\" class=\"filled\"></circle>\n");
    out.push_str("    </marker>\n");
    out.push_str("    <marker id=\"open_circle\" viewBox=\"0 0 8 8\" refX=\"4\" refY=\"4\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n");
    out.push_str("      <circle cx=\"4\" cy=\"4\" r=\"2\" class=\"bg_filled\"></circle>\n");
    out.push_str("    </marker>\n");
    out.push_str("    <marker id=\"big_open_circle\" viewBox=\"0 0 8 8\" refX=\"4\" refY=\"4\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n");
    out.push_str("      <circle cx=\"4\" cy=\"4\" r=\"3\" class=\"bg_filled\"></circle>\n");
    out.push_str("    </marker>\n");
    out.push_str("  </defs>\n");

    // Backdrop rect
    out.push_str("  <rect class=\"backdrop\" x=\"0\" y=\"0\" width=\"");
    fmt_scaled(width_base, s.scale, &mut out);
    out.push_str("\" height=\"");
    fmt_scaled(height_base, s.scale, &mut out);
    out.push_str("\"></rect>\n");

    // Shapes first (all rows), then text per row
    render_shapes(&grid, s.scale, &mut out);

    let classified = classify(&grid);
    for r in 0..grid.num_rows() {
        render_row_texts(&grid, &classified, r, s.scale, &mut out);
    }

    out.push_str("</svg>\n");
    out
}
